import { describe, test, expect, beforeAll } from "bun:test";
import { mkdirSync, existsSync } from "node:fs";
import { probe, extractAudioMp3, extractFrames, ffmpegAvailable } from "../../src/lib/video-iq/media";

// Fixtures are generated by ffmpeg itself (git-ignored): a 3 s landscape clip
// with no audio track and a 3 s vertical clip with a 440 Hz tone.
const DIR = "test-fixtures/video-iq";
const SILENT = `${DIR}/silent-landscape.mp4`;
const TONE = `${DIR}/tone-vertical.mp4`;
let have = false;

beforeAll(async () => {
  have = await ffmpegAvailable();
  if (!have) {
    console.log("ffmpeg missing: media tests skipped");
    return;
  }
  mkdirSync(DIR, { recursive: true });
  if (!existsSync(SILENT)) await Bun.$`ffmpeg -y -v error -f lavfi -i color=c=blue:s=640x360:d=3 -c:v libx264 -pix_fmt yuv420p ${SILENT}`.quiet();
  if (!existsSync(TONE)) await Bun.$`ffmpeg -y -v error -f lavfi -i color=c=red:s=360x640:d=3 -f lavfi -i sine=frequency=440:duration=3 -c:v libx264 -pix_fmt yuv420p -c:a aac -shortest ${TONE}`.quiet();
});

describe("media", () => {
  test("probe reports duration, aspect, audio presence", async () => {
    if (!have) return;
    const a = await probe(SILENT);
    expect(a.hasAudio).toBe(false);
    expect(a.width).toBe(640);
    expect(Math.round(a.durationSec)).toBe(3);
    const b = await probe(TONE);
    expect(b.hasAudio).toBe(true);
    expect(b.height).toBeGreaterThan(b.width);
  });

  test("audio extraction yields mp3 bytes; frames yield jpegs", async () => {
    if (!have) return;
    const mp3 = await extractAudioMp3(TONE);
    expect(mp3.byteLength).toBeGreaterThan(1000);
    const frames = await extractFrames(TONE, [0.5, 1.5]);
    expect(frames.length).toBe(2);
    expect(frames[0][0]).toBe(0xff);
    expect(frames[0][1]).toBe(0xd8);
  });

  test("audio extraction on a silent file throws 'no audio'", async () => {
    if (!have) return;
    await expect(extractAudioMp3(SILENT)).rejects.toThrow(/no audio/);
  });
});
